+
+      var primaryEdges = DATA.edges.filter(function(e) { return e.flow_type !== 'lineage'; });
+      var minTh = d3.min(primaryEdges, function(d) { return d.throughput_gbps; });
+      var maxTh = d3.max(primaryEdges, function(d) { return d.throughput_gbps; });
+      var wScale = d3.scaleLinear().domain([minTh, maxTh]).range([2.5, 9.0]);
+
+      var defs = svg.append('defs');
+
+      function marker(id, color, opacity) {
+        defs.append('marker')
