+        .attr('class', 'axis-label')
+        .attr('fill', tokens.textSecondary)
+        .text('Flow direction →');
+      anno.append('line')
+        .attr('x1', margin.left + 104)
+        .attr('y1', margin.top - 22)
+        .attr('x2', margin.left + 220)
+        .attr('y2', margin.top - 22)
+        .attr('stroke', tokens.link)
+        .attr('stroke-width', 2)
+        .attr('marker-end', 'url(#arrowSolid)')
+        .attr('opacity', 0.9);
+
+      // Highlight online/offline branching with a subtle bracket
+      var bx = farRightX - 5;
+      var byTop = y1;
+      var byMid = y2;
+      var byBot = y3;
+      var bracket = svg.append('g').attr('opacity', 0.9);
+      bracket.append('path')
+        .attr('d', 'M ' + (bx + 58) + ' ' + (byTop - 28) + ' Q ' + (bx + 92) + ' ' + (byTop - 28) + ', ' + (bx + 92) + ' ' + (byTop + 8) +
+                    ' L ' + (bx + 92) + ' ' + (byBot - 8) +
+                    ' Q ' + (bx + 92) + ' ' + (byBot + 28) + ', ' + (bx + 58) + ' ' + (byBot + 28))
+        .attr('fill', 'none')
+        .attr('stroke', tokens.grid)
+        .attr('stroke-width', 2);
+      bracket.append('text')
+        .attr('x', bx + 104)
+        .attr('y', byMid)
+        .attr('text-anchor', 'start')
+        .attr('class', 'axis-label')
+        .attr('fill', tokens.textSecondary)
+        .text('Online / Offline split');
+    }
+
+    var resizeTimer = null;
+    function scheduleRebuild() {
+      if (resizeTimer) window.clearTimeout(resizeTimer);
+      resizeTimer = window.setTimeout(buildVisualization, 60);
+    }
+
+    function onThemeChange() {
+      scheduleRebuild();
+    }
+
+    window.addEventListener('load', function() {
+      buildVisualization();
+      window.addEventListener('resize', scheduleRebuild);
+    });
+  </script>
+</body>
+</html>
+
*** End Patch
PATCH""}

