+        var bend = 0.35;
+        if (kind === 'lineage') bend = 0.55;
+        if (kind === 'feedback') bend = 0.60;
+        var cx1 = sx + dx * bend;
+        var cy1 = sy;
+        var cx2 = tx - dx * bend;
+        var cy2 = ty;
