      marker('arrowSolid', tokens.link, 0.95);
      marker('arrowDash', tokens.linkDashed, 0.90);

      var lanes = [
        { y: y1, label: 'Serving (Online/Realtime)' },
        { y: y2, label: 'Core Pipeline (Training + Deploy)' },
        { y: y3, label: 'Serving (Offline/Batch)' },
        { y: y4, label: 'Experimentation + Observability' }
      ];
      var lane = svg.append('g');
      lane.selectAll('line').data(lanes).enter().append('line')
        .attr('x1', margin.left)
        .attr('x2', width - margin.right)
        .attr('y1', function(d) { return d.y; })
        .attr('y2', function(d) { return d.y; })
        .attr('stroke', tokens.grid)
        .attr('stroke-width', 1);
      lane.selectAll('text').data(lanes).enter().append('text')
        .attr('x', width - margin.right)
        .attr('y', function(d) { return d.y - 12; })
        .attr('text-anchor', 'end')
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text(function(d) { return d.label; });

      function edgePath(source, target, kind) {
        var sx = source.x, sy = source.y;
        var tx = target.x, ty = target.y;
        var dx = tx - sx;
        var dy = ty - sy;
        var bend = 0.35;
        if (kind === 'lineage') bend = 0.55;
        if (kind === 'feedback') bend = 0.60;
        var cx1 = sx + dx * bend;
        var cy1 = sy;
        var cx2 = tx - dx * bend;
        var cy2 = ty;
        if (Math.abs(dy) > 30) {
          cy1 = sy + dy * 0.30;
          cy2 = ty - dy * 0.30;
        }
        return 'M ' + sx + ' ' + sy + ' C ' + cx1 + ' ' + cy1 + ', ' + cx2 + ' ' + cy2 + ', ' + tx + ' ' + ty;
