        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) {
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          revealObserver.unobserve(e.target);
        }
      });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // Data derived directly from benchmark/source_data.json (ml_architecture)
    var DATA = {
      nodes: [
        { id: 'data_platform', label: 'Data Platform\n(Spark / Flink)', layer: 'data', category: 'data-layer', criticality: 9, sub_components: ['Spark', 'Flink', 'Kafka', 'Data Lake'] },
        { id: 'feature_store', label: 'Feature Store', layer: 'data', category: 'data-layer', criticality: 8, sub_components: ['Online Store', 'Offline Store', 'Feature Registry'] },
        { id: 'training_cluster', label: 'Training Cluster\n(GPU)', layer: 'compute', category: 'compute-layer', criticality: 10, sub_components: ['Kubernetes', 'GPU Nodes', 'Distributed Training'] },
        { id: 'model_registry', label: 'Model Registry', layer: 'compute', category: 'compute-layer', criticality: 8, sub_components: ['Model Metadata', 'Artifact Store', 'Promotion Workflow'] },
        { id: 'inference_online', label: 'Inference Service\n(Online / Real-time)', layer: 'serving', category: 'serving-layer', criticality: 9, sub_components: ['Low Latency', 'Autoscaling', 'Canary Deploy'] },
        { id: 'inference_offline', label: 'Inference Service\n(Offline / Batch)', layer: 'serving', category: 'serving-layer', criticality: 7, sub_components: ['Batch Scoring', 'Spark Jobs', 'Backfills'] },
        { id: 'ab_experiment', label: 'A/B Experiment\nPlatform', layer: 'serving', category: 'serving-layer', criticality: 8, sub_components: ['Traffic Split', 'Holdouts', 'Result Store'] },
        { id: 'monitoring', label: 'Monitoring &\nAlerting', layer: 'observability', category: 'observability-layer', criticality: 9, sub_components: ['Metrics', 'Drift Detection', 'Alert Routing'] },
        { id: 'version_control', label: 'Version Control\n& Data Lineage', layer: 'cross-cutting', category: 'observability-layer', criticality: 7, sub_components: ['Git', 'DVC', 'Lineage Graph'] }
      ],
      edges: [
        { source: 'data_platform', target: 'feature_store', flow_type: 'primary', throughput_gbps: 12.5, label: 'Raw → Features' },
        { source: 'feature_store', target: 'training_cluster', flow_type: 'primary', throughput_gbps: 8.0, label: 'Training Data' },
        { source: 'training_cluster', target: 'model_registry', flow_type: 'primary', throughput_gbps: 2.5, label: 'Trained Models' },
        { source: 'model_registry', target: 'inference_online', flow_type: 'primary', throughput_gbps: 1.8, label: 'Model Deploy (Online)' },
        { source: 'model_registry', target: 'inference_offline', flow_type: 'primary', throughput_gbps: 3.2, label: 'Model Deploy (Batch)' },
        { source: 'inference_online', target: 'ab_experiment', flow_type: 'primary', throughput_gbps: 5.0, label: 'Predictions (RT)' },
        { source: 'inference_offline', target: 'ab_experiment', flow_type: 'primary', throughput_gbps: 4.0, label: 'Predictions (Batch)' },
        { source: 'ab_experiment', target: 'monitoring', flow_type: 'primary', throughput_gbps: 2.0, label: 'Metrics & Results' },
        { source: 'monitoring', target: 'data_platform', flow_type: 'feedback', throughput_gbps: 0.5, label: 'Data Quality Alerts' },
        { source: 'monitoring', target: 'training_cluster', flow_type: 'feedback', throughput_gbps: 0.3, label: 'Retrain Trigger' },
        { source: 'version_control', target: 'feature_store', flow_type: 'lineage', throughput_gbps: 0.1, label: 'Feature Versioning' },
        { source: 'version_control', target: 'training_cluster', flow_type: 'lineage', throughput_gbps: 0.1, label: 'Experiment Tracking' },
        { source: 'version_control', target: 'model_registry', flow_type: 'lineage', throughput_gbps: 0.1, label: 'Model Lineage' },
        { source: 'data_platform', target: 'version_control', flow_type: 'lineage', throughput_gbps: 0.2, label: 'Data Lineage' },
        { source: 'feature_store', target: 'inference_online', flow_type: 'primary', throughput_gbps: 6.0, label: 'Online Features' }
      ]
    };

    function themeTokens() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        textSecondary: isDark ? '#9aa0a6' : '#64748b',
        border: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.10)',
        grid: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)',
        link: isDark ? 'rgba(255,255,255,0.55)' : 'rgba(15,23,42,0.45)',
        linkDashed: isDark ? 'rgba(255,255,255,0.42)' : 'rgba(15,23,42,0.35)',
        layer: {
          'data-layer': '#3b82f6',
          'compute-layer': '#10b981',
          'serving-layer': '#f59e0b',
          'observability-layer': '#f43f5e'
        }
      };
    }

    function setLegendSwatches(tokens) {
      var sd = document.getElementById('swData');
      var sc = document.getElementById('swCompute');
      var ss = document.getElementById('swServing');
      var so = document.getElementById('swObs');
      if (sd) sd.style.background = tokens.layer['data-layer'];
      if (sc) sc.style.background = tokens.layer['compute-layer'];
      if (ss) ss.style.background = tokens.layer['serving-layer'];
      if (so) so.style.background = tokens.layer['observability-layer'];
    }

    function buildVisualization() {
      if (typeof d3 === 'undefined') { console.error('D3 not loaded'); return; }
      var wrap = document.getElementById('vizWrap');
      if (!wrap) return;
      wrap.querySelectorAll('svg').forEach(function(n) { n.remove(); });

      var tokens = themeTokens();
      setLegendSwatches(tokens);

      var bbox = wrap.getBoundingClientRect();
      var width = Math.max(880, Math.floor(bbox.width));
      var height = Math.max(640, Math.floor(bbox.height));

      var svg = d3.select(wrap).append('svg')
        .attr('viewBox', '0 0 ' + width + ' ' + height)
        .attr('role', 'img')
        .attr('aria-label', 'Directed ML pipeline architecture graph with throughput and lineage overlay');

      var nodeById = new Map(DATA.nodes.map(function(n) { return [n.id, Object.assign({}, n)]; }));

      var margin = { top: 54, right: 46, bottom: 56, left: 46 };
      var leftX = margin.left + 90;
      var midX = margin.left + Math.round((width - margin.left - margin.right) * 0.43);
      var rightX = margin.left + Math.round((width - margin.left - margin.right) * 0.72);
      var farRightX = width - margin.right - 120;

      var y1 = margin.top + 70;
      var y2 = margin.top + 190;
      var y3 = margin.top + 320;
      var y4 = margin.top + 470;

      var positions = {
        data_platform: { x: leftX, y: y2 },
        feature_store: { x: midX - 40, y: y2 },
        training_cluster: { x: rightX - 40, y: y2 },
        model_registry: { x: farRightX - 10, y: y2 },
        inference_online: { x: farRightX - 5, y: y1 },
        inference_offline: { x: farRightX - 5, y: y3 },
        ab_experiment: { x: rightX + 30, y: y4 },
        monitoring: { x: midX, y: y4 },
        version_control: { x: midX + 20, y: y1 }
      };
      nodeById.forEach(function(n, id) {
        var p = positions[id] || { x: width / 2, y: height / 2 };
        n.x = p.x; n.y = p.y;
      });

      var nodeArr = Array.from(nodeById.values());
      var minCrit = d3.min(nodeArr, function(d) { return d.criticality; });
      var maxCrit = d3.max(nodeArr, function(d) { return d.criticality; });
      var rScale = d3.scaleLinear().domain([minCrit, maxCrit]).range([22, 34]);

      var primaryEdges = DATA.edges.filter(function(e) { return e.flow_type !== 'lineage'; });
      var minTh = d3.min(primaryEdges, function(d) { return d.throughput_gbps; });
      var maxTh = d3.max(primaryEdges, function(d) { return d.throughput_gbps; });
      var wScale = d3.scaleLinear().domain([minTh, maxTh]).range([2.5, 9.0]);

      var defs = svg.append('defs');
      function marker(id, color, opacity) {
        defs.append('marker')
          .attr('id', id)
          .attr('viewBox', '0 0 10 10')
          .attr('refX', 9)
          .attr('refY', 5)
          .attr('markerWidth', 7)
          .attr('markerHeight', 7)
          .attr('orient', 'auto-start-reverse')
          .append('path')
          .attr('d', 'M 0 0 L 10 5 L 0 10 z')
          .attr('fill', color)
          .attr('opacity', opacity);
      }
      marker('arrowSolid', tokens.link, 0.95);
      marker('arrowDash', tokens.linkDashed, 0.90);

      var lanes = [
        { y: y1, label: 'Serving (Online/Realtime)' },
        { y: y2, label: 'Core Pipeline (Training + Deploy)' },
        { y: y3, label: 'Serving (Offline/Batch)' },
        { y: y4, label: 'Experimentation + Observability' }
      ];
      var lane = svg.append('g');
      lane.selectAll('line').data(lanes).enter().append('line')
        .attr('x1', margin.left)
        .attr('x2', width - margin.right)
        .attr('y1', function(d) { return d.y; })
        .attr('y2', function(d) { return d.y; })
        .attr('stroke', tokens.grid)
        .attr('stroke-width', 1);
      lane.selectAll('text').data(lanes).enter().append('text')
        .attr('x', width - margin.right)
        .attr('y', function(d) { return d.y - 12; })
        .attr('text-anchor', 'end')
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text(function(d) { return d.label; });

      function edgePath(source, target, kind) {
        var sx = source.x, sy = source.y;
        var tx = target.x, ty = target.y;
        var dx = tx - sx;
        var dy = ty - sy;
        var bend = 0.35;
        if (kind === 'lineage') bend = 0.55;
        if (kind === 'feedback') bend = 0.60;
        var cx1 = sx + dx * bend;
        var cy1 = sy;
        var cx2 = tx - dx * bend;
        var cy2 = ty;
        if (Math.abs(dy) > 30) {
          cy1 = sy + dy * 0.30;
          cy2 = ty - dy * 0.30;
        }
        return 'M ' + sx + ' ' + sy + ' C ' + cx1 + ' ' + cy1 + ', ' + cx2 + ' ' + cy2 + ', ' + tx + ' ' + ty;
      }

      var edgesWithCoords = DATA.edges.map(function(e) {
        var s = nodeById.get(e.source);
        var t = nodeById.get(e.target);
        return Object.assign({}, e, { s: s, t: t });
      });

      var tooltip = document.getElementById('tooltip');
      function showTip(html, x, y) {
        if (!tooltip) return;
        tooltip.innerHTML = html;
        tooltip.style.left = Math.max(12, Math.min(x + 12, width - 320)) + 'px';
        tooltip.style.top = Math.max(12, Math.min(y + 12, height - 160)) + 'px';
        tooltip.style.opacity = '1';
        tooltip.style.transform = 'translateY(0)';
      }
      function hideTip() {
        if (!tooltip) return;
        tooltip.style.opacity = '0';
        tooltip.style.transform = 'translateY(6px)';
      }

      var gEdges = svg.append('g');
      var gPrimary = gEdges.append('g');
      var gLineage = gEdges.append('g');

      var solidEdges = edgesWithCoords.filter(function(e) { return e.flow_type !== 'lineage'; });
      gPrimary.selectAll('path')
        .data(solidEdges)
        .enter()
        .append('path')
        .attr('d', function(d) { return edgePath(d.s, d.t, d.flow_type); })
        .attr('fill', 'none')
        .attr('stroke', function(d) { return d.flow_type === 'feedback' ? 'rgba(244,63,94,0.70)' : tokens.link; })
        .attr('stroke-width', function(d) { return wScale(d.throughput_gbps); })
        .attr('stroke-linecap', 'round')
        .attr('opacity', function(d) { return d.flow_type === 'feedback' ? 0.85 : 0.9; })
        .attr('marker-end', 'url(#arrowSolid)')
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          showTip(
            '<div class="t1">' + d.label + '</div>' +
            '<div class="t2">' + d.source + ' → ' + d.target + '</div>' +
            '<div class="t3"><b>' + d.throughput_gbps + '</b> Gbps · ' + (d.flow_type === 'feedback' ? 'feedback loop' : 'primary flow') + '</div>',
            p[0], p[1]
          );
        })
        .on('mouseleave', hideTip);

      var dashedEdges = edgesWithCoords.filter(function(e) { return e.flow_type === 'lineage'; });
      gLineage.selectAll('path')
        .data(dashedEdges)
        .enter()
        .append('path')
        .attr('d', function(d) { return edgePath(d.s, d.t, d.flow_type); })
        .attr('fill', 'none')
        .attr('stroke', tokens.linkDashed)
        .attr('stroke-width', 2)
        .attr('stroke-dasharray', '6 6')
        .attr('opacity', 0.85)
        .attr('marker-end', 'url(#arrowDash)')
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          showTip(
            '<div class="t1">' + d.label + '</div>' +
            '<div class="t2">' + d.source + ' → ' + d.target + '</div>' +
            '<div class="t3"><b>' + d.throughput_gbps + '</b> Gbps · lineage/version control</div>',
            p[0], p[1]
          );
        })
        .on('mouseleave', hideTip);

      var keyEdgeIds = new Set([
        'data_platform->feature_store',
        'feature_store->training_cluster',
        'training_cluster->model_registry',
        'model_registry->inference_online',
        'model_registry->inference_offline',
        'feature_store->inference_online',
        'inference_online->ab_experiment',
        'inference_offline->ab_experiment',
        'ab_experiment->monitoring',
        'monitoring->data_platform',
        'monitoring->training_cluster'
      ]);
      var labelEdges = edgesWithCoords.filter(function(e) { return e.flow_type !== 'lineage' && keyEdgeIds.has(e.source + '->' + e.target); });
      var gEdgeLabels = svg.append('g');
      gEdgeLabels.selectAll('text')
        .data(labelEdges)
        .enter()
        .append('text')
        .attr('class', 'edge-label')
        .attr('fill', tokens.textSecondary)
        .attr('text-anchor', 'middle')
        .attr('x', function(d) { return (d.s.x + d.t.x) / 2; })
        .attr('y', function(d) { return (d.s.y + d.t.y) / 2 - 10; })
        .text(function(d) { return d.throughput_gbps + ' Gbps'; });

      var gNodes = svg.append('g');
      var node = gNodes.selectAll('g.node')
        .data(nodeArr)
        .enter()
        .append('g')
        .attr('class', 'node')
        .attr('transform', function(d) { return 'translate(' + d.x + ',' + d.y + ')'; })
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          var subs = (d.sub_components || []).slice(0, 4).join(', ');
          showTip(
            '<div class="t1">' + d.label.split('\n')[0] + '</div>' +
            '<div class="t2">Layer: ' + d.category.replace('-', ' ') + '</div>' +
            '<div class="t3"><b>Criticality:</b> ' + d.criticality + ' / 10' + (subs ? '<br/><b>Includes:</b> ' + subs : '') + '</div>',
            p[0], p[1]
          );
        })
        .on('mouseleave', hideTip);

      node.append('circle')
        .attr('r', function(d) { return rScale(d.criticality) + 7; })
        .attr('fill', function(d) { return tokens.layer[d.category]; })
        .attr('opacity', 0.12);

      node.append('circle')
        .attr('r', function(d) { return rScale(d.criticality); })
        .attr('fill', function(d) { return tokens.layer[d.category]; })
        .attr('stroke', tokens.border)
        .attr('stroke-width', 2)
        .attr('opacity', 0.95);

      node.each(function(d) {
        var g = d3.select(this);
        var lines = (d.label || '').split('\n');
        g.append('text')
          .attr('class', 'node-label')
          .attr('text-anchor', 'middle')
          .attr('y', 5)
          .text(lines[0] || d.id);
        if (lines.length > 1) {
          g.append('text')
            .attr('class', 'node-sublabel')
            .attr('text-anchor', 'middle')
            .attr('y', 22)
            .text(lines.slice(1).join(' '));
        }
      });

      var anno = svg.append('g');
      anno.append('text')
        .attr('x', margin.left)
        .attr('y', margin.top - 18)
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text('Flow direction →');
      anno.append('line')
        .attr('x1', margin.left + 104)
        .attr('y1', margin.top - 22)
        .attr('x2', margin.left + 220)
        .attr('y2', margin.top - 22)
        .attr('stroke', tokens.link)
        .attr('stroke-width', 2)
        .attr('marker-end', 'url(#arrowSolid)')
        .attr('opacity', 0.9);

      var bx = farRightX - 5;
      var byTop = y1;
      var byMid = y2;
      var byBot = y3;
      var bracket = svg.append('g').attr('opacity', 0.9);
      bracket.append('path')
        .attr('d', 'M ' + (bx + 58) + ' ' + (byTop - 28) + ' Q ' + (bx + 92) + ' ' + (byTop - 28) + ', ' + (bx + 92) + ' ' + (byTop + 8) +
                    ' L ' + (bx + 92) + ' ' + (byBot - 8) +
                    ' Q ' + (bx + 92) + ' ' + (byBot + 28) + ', ' + (bx + 58) + ' ' + (byBot + 28))
        .attr('fill', 'none')
        .attr('stroke', tokens.grid)
        .attr('stroke-width', 2);
      bracket.append('text')
        .attr('x', bx + 104)
        .attr('y', byMid)
        .attr('text-anchor', 'start')
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text('Online / Offline split');
    }

    var resizeTimer = null;
    function scheduleRebuild() {
      if (resizeTimer) window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(buildVisualization, 60);
    }
    function onThemeChange() { scheduleRebuild(); }

    window.addEventListener('load', function() {
      buildVisualization();
      window.addEventListener('resize', scheduleRebuild);
    });
  </script>
</body>
</html>
EOF'"}

