        .attr('fill', 'none')
        .attr('stroke', function(d) { return d.flow_type === 'feedback' ? 'rgba(244,63,94,0.70)' : tokens.link; })
        .attr('stroke-width', function(d) { return wScale(d.throughput_gbps); })
        .attr('stroke-linecap', 'round')
        .attr('opacity', function(d) { return d.flow_type === 'feedback' ? 0.85 : 0.9; })
