            '<div class="t3"><b>' + d.throughput_gbps + '</b> Gbps · ' + (d.flow_type === 'feedback' ? 'feedback loop' : 'primary flow') + '</div>',
            p[0], p[1]
          );
        })
        .on('mouseleave', hideTip);

      var dashedEdges = edgesWithCoords.filter(function(e) { return e.flow_type === 'lineage'; });
      gLineage.selectAll('path')
        .data(dashedEdges)
        .enter()
        .append('path')
        .attr('d', function(d) { return edgePath(d.s, d.t, d.flow_type); })
        .attr('fill', 'none')
        .attr('stroke', tokens.linkDashed)
        .attr('stroke-width', 2)
        .attr('stroke-dasharray', '6 6')
        .attr('opacity', 0.85)
        .attr('marker-end', 'url(#arrowDash)')
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          showTip(
            '<div class="t1">' + d.label + '</div>' +
            '<div class="t2">' + d.source + ' → ' + d.target + '</div>' +
            '<div class="t3"><b>' + d.throughput_gbps + '</b> Gbps · lineage/version control</div>',
            p[0], p[1]
          );
        })
        .on('mouseleave', hideTip);

      var keyEdgeIds = new Set([
        'data_platform->feature_store',
        'feature_store->training_cluster',
        'training_cluster->model_registry',
        'model_registry->inference_online',
        'model_registry->inference_offline',
        'feature_store->inference_online',
        'inference_online->ab_experiment',
        'inference_offline->ab_experiment',
        'ab_experiment->monitoring',
        'monitoring->data_platform',
        'monitoring->training_cluster'
      ]);
      var labelEdges = edgesWithCoords.filter(function(e) { return e.flow_type !== 'lineage' && keyEdgeIds.has(e.source + '->' + e.target); });
      var gEdgeLabels = svg.append('g');
      gEdgeLabels.selectAll('text')
        .data(labelEdges)
        .enter()
        .append('text')
        .attr('class', 'edge-label')
        .attr('fill', tokens.textSecondary)
        .attr('text-anchor', 'middle')
        .attr('x', function(d) { return (d.s.x + d.t.x) / 2; })
