      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }

    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    .page { max-width: 1200px; margin: 0 auto; padding: 28px 22px 40px; }
    header.hero { display: grid; grid-template-columns: 1.4fr 1fr; gap: 16px; align-items: start; margin-bottom: 14px; }
    .hero h1 { font-size: 26px; }
    .hero p { margin-top: 8px; color: var(--text-secondary); }
    .meta { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
    .meta .pill { border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px; background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0)); }
    .pill .k { font-size: 12px; color: var(--text-secondary); }
    .pill .v { font-size: 14px; font-weight: 600; margin-top: 2px; }

    .viz-wrap { height: 720px; position: relative; overflow: hidden; }
    svg { display: block; width: 100%; height: 100%; }

    .legend { display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center; margin-top: 10px; }
    .legend-item { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-secondary); }
    .swatch { width: 10px; height: 10px; border-radius: 3px; border: 1px solid rgba(255,255,255,0.12); }
    .line-swatch { width: 22px; height: 0; border-top: 3px solid rgba(255,255,255,0.55); border-radius: 2px; }
    .line-swatch.dashed { border-top-style: dashed; border-top-width: 3px; border-top-color: rgba(255,255,255,0.45); }

    .axis-label { font-size: 12px; fill: var(--text-secondary); letter-spacing: 0.02em; }
    .node-label { font-size: 12px; fill: var(--text); font-weight: 600; paint-order: stroke; stroke: rgba(0,0,0,0.65); stroke-width: 3px; stroke-linejoin: round; }
    .node-sublabel { font-size: 11px; fill: var(--text-secondary); paint-order: stroke; stroke: rgba(0,0,0,0.55); stroke-width: 3px; stroke-linejoin: round; }
    .edge-label { font-size: 10.5px; fill: var(--text-secondary); paint-order: stroke; stroke: rgba(0,0,0,0.75); stroke-width: 3px; stroke-linejoin: round; }
    .panel-note { margin-top: 8px; font-size: 12px; color: var(--text-secondary); }

    .tooltip {
      position: absolute; pointer-events: none; opacity: 0; transform: translateY(6px);
      transition: opacity 0.12s ease, transform 0.12s ease;
      background: rgba(20,20,20,0.92); border: 1px solid rgba(255,255,255,0.08);
      padding: 10px 12px; border-radius: 10px; max-width: 300px;
      box-shadow: 0 10px 24px rgba(0,0,0,0.35); backdrop-filter: blur(10px); z-index: 10;
    }
    html.theme-light .tooltip { background: rgba(255,255,255,0.92); border: 1px solid rgba(0,0,0,0.08); box-shadow: 0 10px 24px rgba(0,0,0,0.12); }
    .tooltip .t1 { font-size: 12px; font-weight: 700; color: var(--text); }
    .tooltip .t2 { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }
    .tooltip .t3 { font-size: 12px; color: var(--text-secondary); margin-top: 6px; }

    @media (max-width: 980px) { header.hero { grid-template-columns: 1fr; } .viz-wrap { height: 760px; } }
  </style>
</head>
<body>
  <a href=\"#main-content\" class=\"skip-to-content\">Skip to content</a>

  <div class=\"viz-menu\">
    <button class=\"viz-menu-toggle\" onclick=\"toggleMenu()\" aria-label=\"Menu\">
      <svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">
        <line x1=\"3\" y1=\"5\" x2=\"17\" y2=\"5\"/>
        <line x1=\"3\" y1=\"10\" x2=\"17\" y2=\"10\"/>
        <line x1=\"3\" y1=\"15\" x2=\"17\" y2=\"15\"/>
      </svg>
    </button>
    <div class=\"viz-menu-dropdown\" id=\"vizMenuDropdown\">
      <button onclick=\"cycleTheme()\"><span id=\"themeIcon\">🌙</span><span id=\"themeLabel\">Dark</span></button>
      <button onclick=\"downloadImage()\"><span>📥</span><span>Download PNG</span></button>
      <button onclick=\"window.print()\"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <main id=\"main-content\" role=\"main\">
    <div class=\"page\">
      <section class=\"animate\">
        <header class=\"hero\">
          <div>
            <h1>${escHtml(title)}</h1>
            <p>
              Directed architecture from <span style=\"color: var(--accent); font-weight: 600;\">Data Platform</span> → Feature Store → Training → Registry → Inference (online/offline) → A/B Experiments → Monitoring.
              Node color encodes layer; node size encodes criticality (${minCrit}–${maxCrit}). Edge width encodes throughput (Gbps).
              Dashed links represent version control &amp; lineage overlay.
            </p>
          </div>
          <div class=\"meta\">
            <div class=\"pill\"><div class=\"k\">Throughput range</div><div class=\"v\">${minTh.toFixed(1)}–${maxTh.toFixed(1)} Gbps</div></div>
            <div class=\"pill\"><div class=\"k\">Encoding</div><div class=\"v\">Width = throughput · Size = criticality</div></div>
            <div class=\"pill\"><div class=\"k\">Branching</div><div class=\"v\">Inference splits online/offline</div></div>
            <div class=\"pill\"><div class=\"k\">Closed loop</div><div class=\"v\">Monitoring feeds data + retrain</div></div>
          </div>
        </header>
      </section>

      <section class=\"card\" data-reveal aria-label=\"ML pipeline architecture chart\">
        <div class=\"viz-wrap\" id=\"vizWrap\">
          <div class=\"tooltip\" id=\"tooltip\" role=\"status\" aria-live=\"polite\"></div>
        </div>
        <div class=\"legend\" aria-label=\"Legend\">
          <span class=\"legend-item\"><span class=\"swatch\" id=\"swData\"></span>Data layer</span>
          <span class=\"legend-item\"><span class=\"swatch\" id=\"swCompute\"></span>Compute layer</span>
          <span class=\"legend-item\"><span class=\"swatch\" id=\"swServing\"></span>Serving layer</span>
          <span class=\"legend-item\"><span class=\"swatch\" id=\"swObs\"></span>Observability layer</span>
          <span class=\"legend-item\"><span class=\"line-swatch\"></span>Primary/feedback flow (solid)</span>
          <span class=\"legend-item\"><span class=\"line-swatch dashed\"></span>Version control &amp; lineage (dashed)</span>
        </div>
        <div class=\"panel-note\">Units: throughput in <b>Gbps</b>. Hover nodes/edges for details.</div>
      </section>
    </div>
  </main>

  <script>
    function toggleMenu() { var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu'); if (dropdown) dropdown.classList.toggle('open'); }
    document.addEventListener('click', function(e) { if (!e.target.closest('.viz-menu')) { var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu'); if (dropdown) dropdown.classList.remove('open'); } });
    document.addEventListener('keydown', function(e) { if (e.key === 'Escape') { var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu'); if (dropdown) dropdown.classList.remove('open'); } });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    var DATA = ${JSON.stringify({ nodes, edges })};

    function themeTokens() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        textSecondary: isDark ? '#9aa0a6' : '#64748b',
        border: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.10)',
        grid: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)',
        link: isDark ? 'rgba(255,255,255,0.55)' : 'rgba(15,23,42,0.45)',
        linkDashed: isDark ? 'rgba(255,255,255,0.42)' : 'rgba(15,23,42,0.35)',
        layer: {
          'data-layer': '#3b82f6',
          'compute-layer': '#10b981',
          'serving-layer': '#f59e0b',
          'observability-layer': '#f43f5e'
        }
      };
    }
    function setLegendSwatches(tokens) {
      var sd = document.getElementById('swData');
      var sc = document.getElementById('swCompute');
      var ss = document.getElementById('swServing');
      var so = document.getElementById('swObs');
      if (sd) sd.style.background = tokens.layer['data-layer'];
      if (sc) sc.style.background = tokens.layer['compute-layer'];
      if (ss) ss.style.background = tokens.layer['serving-layer'];
      if (so) so.style.background = tokens.layer['observability-layer'];
    }

    function buildVisualization() {
      if (typeof d3 === 'undefined') { console.error('D3 not loaded'); return; }
      var wrap = document.getElementById('vizWrap');
      if (!wrap) return;
      wrap.querySelectorAll('svg').forEach(function(n) { n.remove(); });

      var tokens = themeTokens();
      setLegendSwatches(tokens);

      var bbox = wrap.getBoundingClientRect();
      var width = Math.max(880, Math.floor(bbox.width));
      var height = Math.max(640, Math.floor(bbox.height));

      var svg = d3.select(wrap).append('svg')
        .attr('viewBox', '0 0 ' + width + ' ' + height)
        .attr('role', 'img')
        .attr('aria-label', 'Directed ML pipeline architecture graph with throughput and lineage overlay');

      var nodeById = new Map(DATA.nodes.map(function(n) { return [n.id, Object.assign({}, n)]; }));

      var margin = { top: 54, right: 46, bottom: 56, left: 46 };
      var leftX = margin.left + 90;
      var midX = margin.left + Math.round((width - margin.left - margin.right) * 0.43);
      var rightX = margin.left + Math.round((width - margin.left - margin.right) * 0.72);
      var farRightX = width - margin.right - 120;

      var y1 = margin.top + 70;
      var y2 = margin.top + 190;
      var y3 = margin.top + 320;
      var y4 = margin.top + 470;

      var positions = {
        data_platform: { x: leftX, y: y2 },
        feature_store: { x: midX - 40, y: y2 },
        training_cluster: { x: rightX - 40, y: y2 },
        model_registry: { x: farRightX - 10, y: y2 },
        inference_online: { x: farRightX - 5, y: y1 },
        inference_offline: { x: farRightX - 5, y: y3 },
        ab_experiment: { x: rightX + 30, y: y4 },
        monitoring: { x: midX, y: y4 },
        version_control: { x: midX + 20, y: y1 }
      };
      nodeById.forEach(function(n, id) {
        var p = positions[id] || { x: width / 2, y: height / 2 };
        n.x = p.x; n.y = p.y;
      });

      var nodeArr = Array.from(nodeById.values());
      var minCrit = d3.min(nodeArr, function(d) { return d.criticality; });
      var maxCrit = d3.max(nodeArr, function(d) { return d.criticality; });
      var rScale = d3.scaleLinear().domain([minCrit, maxCrit]).range([22, 34]);

      var nonLineage = DATA.edges.filter(function(e) { return e.flow_type !== 'lineage'; });
      var minTh = d3.min(nonLineage, function(d) { return d.throughput_gbps; });
      var maxTh = d3.max(nonLineage, function(d) { return d.throughput_gbps; });
      var wScale = d3.scaleLinear().domain([minTh, maxTh]).range([2.5, 9.0]);

      var defs = svg.append('defs');
      function marker(id, color, opacity) {
        defs.append('marker')
          .attr('id', id)
          .attr('viewBox', '0 0 10 10')
          .attr('refX', 9)
          .attr('refY', 5)
          .attr('markerWidth', 7)
          .attr('markerHeight', 7)
          .attr('orient', 'auto-start-reverse')
          .append('path')
          .attr('d', 'M 0 0 L 10 5 L 0 10 z')
          .attr('fill', color)
          .attr('opacity', opacity);
      }
      marker('arrowSolid', tokens.link, 0.95);
      marker('arrowDash', tokens.linkDashed, 0.90);

      var lanes = [
        { y: y1, label: 'Serving (Online/Realtime)' },
        { y: y2, label: 'Core Pipeline (Training + Deploy)' },
        { y: y3, label: 'Serving (Offline/Batch)' },
        { y: y4, label: 'Experimentation + Observability' }
      ];
      var lane = svg.append('g');
      lane.selectAll('line').data(lanes).enter().append('line')
        .attr('x1', margin.left)
        .attr('x2', width - margin.right)
        .attr('y1', function(d) { return d.y; })
        .attr('y2', function(d) { return d.y; })
        .attr('stroke', tokens.grid)
        .attr('stroke-width', 1);
      lane.selectAll('text').data(lanes).enter().append('text')
        .attr('x', width - margin.right)
        .attr('y', function(d) { return d.y - 12; })
        .attr('text-anchor', 'end')
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text(function(d) { return d.label; });

      function edgePath(source, target, kind) {
        var sx = source.x, sy = source.y;
        var tx = target.x, ty = target.y;
        var dx = tx - sx;
        var dy = ty - sy;
        var bend = 0.35;
        if (kind === 'lineage') bend = 0.55;
        if (kind === 'feedback') bend = 0.60;
        var cx1 = sx + dx * bend;
        var cy1 = sy;
        var cx2 = tx - dx * bend;
        var cy2 = ty;
        if (Math.abs(dy) > 30) {
          cy1 = sy + dy * 0.30;
          cy2 = ty - dy * 0.30;
        }
        return 'M ' + sx + ' ' + sy + ' C ' + cx1 + ' ' + cy1 + ', ' + cx2 + ' ' + cy2 + ', ' + tx + ' ' + ty;
      }

      var edgesWithCoords = DATA.edges.map(function(e) {
        var s = nodeById.get(e.source);
        var t = nodeById.get(e.target);
        return Object.assign({}, e, { s: s, t: t });
      });

      var tooltip = document.getElementById('tooltip');
      function showTip(html, x, y) {
        if (!tooltip) return;
        tooltip.innerHTML = html;
        tooltip.style.left = Math.max(12, Math.min(x + 12, width - 320)) + 'px';
        tooltip.style.top = Math.max(12, Math.min(y + 12, height - 160)) + 'px';
        tooltip.style.opacity = '1';
        tooltip.style.transform = 'translateY(0)';
      }
      function hideTip() {
        if (!tooltip) return;
        tooltip.style.opacity = '0';
        tooltip.style.transform = 'translateY(6px)';
      }

      var gEdges = svg.append('g');
      var gPrimary = gEdges.append('g');
      var gLineage = gEdges.append('g');

      var solidEdges = edgesWithCoords.filter(function(e) { return e.flow_type !== 'lineage'; });
      gPrimary.selectAll('path').data(solidEdges).enter().append('path')
        .attr('d', function(d) { return edgePath(d.s, d.t, d.flow_type); })
        .attr('fill', 'none')
        .attr('stroke', function(d) { return d.flow_type === 'feedback' ? 'rgba(244,63,94,0.70)' : tokens.link; })
        .attr('stroke-width', function(d) { return wScale(d.throughput_gbps); })
        .attr('stroke-linecap', 'round')
        .attr('opacity', function(d) { return d.flow_type === 'feedback' ? 0.85 : 0.9; })
        .attr('marker-end', 'url(#arrowSolid)')
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          showTip('<div class="t1">' + d.label + '</div><div class="t2">' + d.source + ' → ' + d.target + '</div><div class="t3"><b>' + d.throughput_gbps + '</b> Gbps · ' + (d.flow_type === 'feedback' ? 'feedback loop' : 'primary flow') + '</div>', p[0], p[1]);
        })
        .on('mouseleave', hideTip);

      var dashedEdges = edgesWithCoords.filter(function(e) { return e.flow_type === 'lineage'; });
      gLineage.selectAll('path').data(dashedEdges).enter().append('path')
        .attr('d', function(d) { return edgePath(d.s, d.t, d.flow_type); })
        .attr('fill', 'none')
        .attr('stroke', tokens.linkDashed)
        .attr('stroke-width', 2)
        .attr('stroke-dasharray', '6 6')
        .attr('opacity', 0.85)
        .attr('marker-end', 'url(#arrowDash)')
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          showTip('<div class="t1">' + d.label + '</div><div class="t2">' + d.source + ' → ' + d.target + '</div><div class="t3"><b>' + d.throughput_gbps + '</b> Gbps · lineage/version control</div>', p[0], p[1]);
        })
        .on('mouseleave', hideTip);

      var keyEdgeIds = new Set([
        'data_platform->feature_store',
        'feature_store->training_cluster',
        'training_cluster->model_registry',
        'model_registry->inference_online',
        'model_registry->inference_offline',
        'feature_store->inference_online',
        'inference_online->ab_experiment',
        'inference_offline->ab_experiment',
        'ab_experiment->monitoring',
        'monitoring->data_platform',
        'monitoring->training_cluster'
      ]);
      var labelEdges = edgesWithCoords.filter(function(e) { return e.flow_type !== 'lineage' && keyEdgeIds.has(e.source + '->' + e.target); });
      svg.append('g').selectAll('text').data(labelEdges).enter().append('text')
        .attr('class', 'edge-label')
        .attr('fill', tokens.textSecondary)
        .attr('text-anchor', 'middle')
        .attr('x', function(d) { return (d.s.x + d.t.x) / 2; })
        .attr('y', function(d) { return (d.s.y + d.t.y) / 2 - 10; })
        .text(function(d) { return d.throughput_gbps + ' Gbps'; });

      var node = svg.append('g').selectAll('g.node').data(nodeArr).enter().append('g')
        .attr('class', 'node')
        .attr('transform', function(d) { return 'translate(' + d.x + ',' + d.y + ')'; })
        .style('cursor', 'help')
        .on('mousemove', function(event, d) {
          var p = d3.pointer(event, svg.node());
          var subs = (d.sub_components || []).slice(0, 4).join(', ');
          showTip('<div class="t1">' + String(d.label).split('\\n')[0] + '</div><div class="t2">Layer: ' + String(d.category).replace('-', ' ') + '</div><div class="t3"><b>Criticality:</b> ' + d.criticality + ' / 10' + (subs ? '<br/><b>Includes:</b> ' + subs : '') + '</div>', p[0], p[1]);
        })
        .on('mouseleave', hideTip);

      node.append('circle')
        .attr('r', function(d) { return rScale(d.criticality) + 7; })
        .attr('fill', function(d) { return tokens.layer[d.category]; })
        .attr('opacity', 0.12);
      node.append('circle')
        .attr('r', function(d) { return rScale(d.criticality); })
        .attr('fill', function(d) { return tokens.layer[d.category]; })
        .attr('stroke', tokens.border)
        .attr('stroke-width', 2)
        .attr('opacity', 0.95);

      node.each(function(d) {
        var g = d3.select(this);
        var lines = String(d.label || '').split('\\n');
        g.append('text').attr('class', 'node-label').attr('text-anchor', 'middle').attr('y', 5).text(lines[0] || d.id);
        if (lines.length > 1) {
          g.append('text').attr('class', 'node-sublabel').attr('text-anchor', 'middle').attr('y', 22).text(lines.slice(1).join(' '));
        }
      });

      var anno = svg.append('g');
      anno.append('text')
        .attr('x', margin.left)
        .attr('y', margin.top - 18)
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text('Flow direction →');
      anno.append('line')
        .attr('x1', margin.left + 104)
        .attr('y1', margin.top - 22)
        .attr('x2', margin.left + 220)
        .attr('y2', margin.top - 22)
        .attr('stroke', tokens.link)
        .attr('stroke-width', 2)
        .attr('marker-end', 'url(#arrowSolid)')
        .attr('opacity', 0.9);

      var bx = farRightX - 5;
      var byTop = y1;
      var byMid = y2;
      var byBot = y3;
      var bracket = svg.append('g').attr('opacity', 0.9);
      bracket.append('path')
        .attr('d', 'M ' + (bx + 58) + ' ' + (byTop - 28) + ' Q ' + (bx + 92) + ' ' + (byTop - 28) + ', ' + (bx + 92) + ' ' + (byTop + 8) +\
                    ' L ' + (bx + 92) + ' ' + (byBot - 8) +\
                    ' Q ' + (bx + 92) + ' ' + (byBot + 28) + ', ' + (bx + 58) + ' ' + (byBot + 28))
        .attr('fill', 'none')
        .attr('stroke', tokens.grid)
        .attr('stroke-width', 2);
      bracket.append('text')
        .attr('x', bx + 104)
        .attr('y', byMid)
        .attr('text-anchor', 'start')
        .attr('class', 'axis-label')
        .attr('fill', tokens.textSecondary)
        .text('Online / Offline split');
    }

    var resizeTimer = null;
